WITH targets AS (SELECT to_regclass(n) oid FROM unnest(ARRAY['public.assignments','public.assist_visits','public.assist_visit_proofs','public.assist_visit_signatures','public.assist_visit_documentation','public.assist_time_events','public.assist_visit_tasks','public.assignment_tasks','public.service_records','public.invoices','public.clients','public.employees','public.tenants','public.profiles','public.roles','public.role_permissions','public.employee_portal_accounts','public.tenant_billing_settings','public.tenant_bank_accounts','public.tenant_branding','public.document_render_jobs','public.client_budgets','public.billing_runs','storage.objects','auth.users','auth.sessions']) n), rows(k,v) AS (
 SELECT 'table/'||c.oid::regclass::text,jsonb_build_array(c.relrowsecurity,c.relforcerowsecurity,c.relacl,
 (SELECT jsonb_agg(jsonb_build_array(a.attname,format_type(a.atttypid,a.atttypmod),a.attnotnull,pg_get_expr(d.adbin,d.adrelid)) ORDER BY a.attnum) FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped))
 FROM pg_class c WHERE c.oid IN(SELECT oid FROM targets)
 UNION ALL SELECT 'constraint/'||conrelid::regclass||'/'||conname,to_jsonb(pg_get_constraintdef(oid)) FROM pg_constraint WHERE conrelid IN(SELECT oid FROM targets)
 UNION ALL SELECT 'trigger/'||tgrelid::regclass||'/'||tgname,jsonb_build_array(pg_get_triggerdef(oid),tgenabled,pg_get_functiondef(tgfoid)) FROM pg_trigger WHERE tgrelid IN(SELECT oid FROM targets) AND NOT tgisinternal
 UNION ALL SELECT 'policy/'||polrelid::regclass||'/'||polname,jsonb_build_array(polcmd,polpermissive,polroles,pg_get_expr(polqual,polrelid),pg_get_expr(polwithcheck,polrelid)) FROM pg_policy WHERE polrelid IN(SELECT oid FROM targets)
 UNION ALL SELECT 'function/'||p.oid::regprocedure::text,to_jsonb(pg_get_functiondef(p.oid)) FROM pg_proc p WHERE p.proname IN('workflow_canonical_json','workflow_tasks_match','workflow_record_actor_allowed','office_actor','gkv_exchange_actor','generated_pdf_reader')
) SELECT encode(sha256(convert_to(jsonb_agg(jsonb_build_array(k,v) ORDER BY k COLLATE "C")::text,'UTF8')),'hex') digest FROM rows;
